package com.bloodcare.api;

import com.bloodcare.model.*;
import com.bloodcare.model.Models.*;
import com.bloodcare.repository.*;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.*;
import org.springframework.security.core.context.*;
import org.springframework.security.crypto.password.PasswordEncoder;
 import org.springframework.security.web.context.HttpSessionSecurityContextRepository;
 import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;

@RestController @RequestMapping("/api")
public class ApiController {
 private final UserRepo users; private final DonorRepo donors; private final RequestRepo requests; private final DonationRepo donations; private final HistoryRepo history; private final PasswordEncoder encoder; private final AuthenticationManager auth;
 public ApiController(UserRepo u,DonorRepo d,RequestRepo r,DonationRepo n,HistoryRepo h,PasswordEncoder e,AuthenticationManager a){users=u;donors=d;requests=r;donations=n;history=h;encoder=e;auth=a;}
 public record AuthInput(@Email @NotBlank String email,@NotBlank String password){}
 public record RegisterInput(@NotBlank String fullName,@Email @NotBlank String email,@NotBlank @Pattern(regexp="[+0-9 ()-]{7,20}") String phone,@NotBlank @Size(min=8,max=72) String password,String role,@Min(18) @Max(100) Integer age,String gender,String bloodGroup,String city,String state,String address,Boolean available){}
 public record ProfileInput(@NotBlank String fullName,@Pattern(regexp="[+0-9 ()-]{7,20}") String phone,@Min(18) @Max(100) Integer age,String gender,String bloodGroup,String city,String state,String address,Boolean available){}
 public record RequestInput(@NotBlank String patientName,@NotBlank String bloodGroup,@Positive Integer unitsRequired,@NotBlank String hospitalName,@NotBlank String hospitalLocation,@NotBlank @Pattern(regexp="[+0-9 ()-]{7,20}") String contactNumber,@NotBlank String urgency,@jakarta.validation.constraints.NotNull LocalDate requiredDate,String notes){}
 public record StatusInput(String status,String remarks){}
 public record AvailabilityInput(Boolean available){}
 public record UserView(Long id,String fullName,String email,String phone,String role,boolean enabled){}
 public record DonorView(Long id,String name,String bloodGroup,String city,String state,String phone,boolean available,int age,String gender){}
 public record RequestView(Long id,String patientName,String bloodGroup,int unitsRequired,String hospitalName,String hospitalLocation,String contactNumber,String urgency,LocalDate requiredDate,String status,String notes,LocalDateTime createdAt,String requesterName){}
 private User current(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||a.getName().equals("anonymousUser"))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Sign in required");return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 @GetMapping("/auth/csrf") public Map<String,String> csrf(CsrfToken token){return Map.of("token",token.getToken());}
 private static BloodGroup group(String value){try{return BloodGroup.valueOf(value.toUpperCase().replace('+', '_').replace('-', '_').replace("_POS","_POS").replace("_NEG","_NEG"));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a valid blood group (A_POS, A_NEG, B_POS, B_NEG, AB_POS, AB_NEG, O_POS, O_NEG)");}}
 private UserView uv(User u){return new UserView(u.id,u.fullName,u.email,u.phone,u.role.name(),u.enabled);}
 private DonorView dv(Donor d){return new DonorView(d.id,d.user.fullName,d.bloodGroup.name(),d.city,d.state,d.user.phone,d.available,d.age,d.gender);}
 private RequestView rv(BloodRequest r){return new RequestView(r.id,r.patientName,r.bloodGroup.name(),r.unitsRequired,r.hospitalName,r.hospitalLocation,r.contactNumber,r.urgency.name(),r.requiredDate,r.status.name(),r.notes,r.createdAt,r.requester.fullName);}
 @PostMapping("/auth/register") @Transactional public ResponseEntity<?> register(@Valid @RequestBody RegisterInput in){if(users.findByEmailIgnoreCase(in.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");Role role="DONOR".equalsIgnoreCase(in.role())?Role.DONOR:Role.REQUESTER;User u=new User();u.fullName=in.fullName().trim();u.email=in.email().trim().toLowerCase();u.phone=in.phone();u.passwordHash=encoder.encode(in.password());u.role=role;users.save(u);if(role==Role.DONOR){Donor d=new Donor();d.user=u;d.age=in.age()==null?18:in.age();d.gender=Objects.requireNonNullElse(in.gender(),"Unspecified");d.bloodGroup=group(in.bloodGroup());d.city=Objects.requireNonNullElse(in.city(),"");d.state=Objects.requireNonNullElse(in.state(),"");d.address=Objects.requireNonNullElse(in.address(),"");d.available=in.available()==null||in.available();donors.save(d);}return ResponseEntity.status(201).body(Map.of("message","Account created. Please sign in."));}
 @PostMapping("/auth/login") public UserView login(@Valid @RequestBody AuthInput in,HttpServletRequest req){Authentication a=auth.authenticate(new UsernamePasswordAuthenticationToken(in.email().toLowerCase(),in.password()));SecurityContext c=SecurityContextHolder.createEmptyContext();c.setAuthentication(a);SecurityContextHolder.setContext(c);req.getSession(true).setAttribute(HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,c);return uv(current());}
 @PostMapping("/auth/logout") public Map<String,String> logout(HttpServletRequest req){req.getSession(false);SecurityContextHolder.clearContext();if(req.getSession(false)!=null)req.getSession(false).invalidate();return Map.of("message","Signed out");}
 @GetMapping("/auth/me") public UserView me(){return uv(current());}
 @GetMapping("/donors/search") public List<DonorView> search(@RequestParam(required=false) String bloodGroup,@RequestParam(required=false) String city,@RequestParam(required=false) String state){return donors.search(bloodGroup==null||bloodGroup.isBlank()?null:group(bloodGroup),blank(city),blank(state)).stream().map(this::dv).toList();}
 @GetMapping("/donors/available") public List<DonorView> available(){return donors.search(null,null,null).stream().map(this::dv).toList();}
 @GetMapping("/donors") public List<DonorView> donorList(@RequestParam(required=false) String bloodGroup,@RequestParam(required=false) String city,@RequestParam(required=false) String state){return search(bloodGroup,city,state);}
 @GetMapping("/donors/me") public DonorView myDonor(){User u=current();return dv(donors.findByUserId(u.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Donor profile not found")));}
 @PutMapping("/donors/me") @Transactional public DonorView updateProfile(@Valid @RequestBody ProfileInput in){User u=current();Donor d=donors.findByUserId(u.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Donor profile not found"));u.fullName=in.fullName();u.phone=in.phone();d.age=in.age();d.gender=in.gender();d.bloodGroup=group(in.bloodGroup());d.city=in.city();d.state=in.state();d.address=in.address();d.available=in.available()==null?d.available:in.available();u.updatedAt=d.updatedAt=LocalDateTime.now();return dv(donors.save(d));}
 @PatchMapping("/donors/me/availability") public DonorView availability(@RequestBody AvailabilityInput in){Donor d=donors.findByUserId(current().id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Donor profile not found"));d.available=Boolean.TRUE.equals(in.available());return dv(donors.save(d));}
 @PostMapping("/requests") @Transactional public ResponseEntity<RequestView> createRequest(@Valid @RequestBody RequestInput in){User requester=current();if(requester.role!=Role.REQUESTER)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Requester accounts may submit blood requests");BloodRequest r=new BloodRequest();r.requester=requester;r.patientName=in.patientName();r.bloodGroup=group(in.bloodGroup());r.unitsRequired=in.unitsRequired();r.hospitalName=in.hospitalName();r.hospitalLocation=in.hospitalLocation();r.contactNumber=in.contactNumber();try{r.urgency=Urgency.valueOf(in.urgency().toUpperCase());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid urgency");}r.requiredDate=in.requiredDate();r.notes=in.notes();return ResponseEntity.status(201).body(rv(requests.save(r)));}
 @GetMapping("/requests/my") public List<RequestView> myRequests(){return requests.findByRequesterIdOrderByCreatedAtDesc(current().id).stream().map(this::rv).toList();}
 @GetMapping("/requests/{id}") public RequestView request(@PathVariable Long id){BloodRequest r=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Request not found"));if(!r.requester.id.equals(current().id)&&current().role!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your request");return rv(r);}
 @PatchMapping("/requests/{id}/cancel") @Transactional public RequestView cancel(@PathVariable Long id){BloodRequest r=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Request not found"));if(!r.requester.id.equals(current().id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your request");if(r.status!=RequestStatus.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending requests can be cancelled");setStatus(r,RequestStatus.CANCELLED,current(),"Cancelled by requester");return rv(r);}
 @GetMapping("/admin/requests") public List<RequestView> allRequests(){return requests.findAll().stream().sorted(Comparator.comparing(x->x.createdAt,Comparator.reverseOrder())).map(this::rv).toList();}
 @PatchMapping("/admin/requests/{id}/status") @Transactional public RequestView status(@PathVariable Long id,@RequestBody StatusInput in){BloodRequest r=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Request not found"));RequestStatus next;try{next=RequestStatus.valueOf(in.status().toUpperCase());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");}if(!allowed(r.status,next))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid request status transition");setStatus(r,next,current(),in.remarks());return rv(r);}
 private boolean allowed(RequestStatus from,RequestStatus to){return switch(from){case PENDING->to==RequestStatus.APPROVED||to==RequestStatus.REJECTED;case APPROVED->to==RequestStatus.FULFILLED||to==RequestStatus.REJECTED;default->false;};}
 private void setStatus(BloodRequest r,RequestStatus s,User by,String remark){StatusHistory h=new StatusHistory();h.bloodRequest=r;h.previousStatus=r.status;h.newStatus=s;h.changedBy=by;h.remarks=remark;history.save(h);r.status=s;r.updatedAt=LocalDateTime.now();requests.save(r);}
 @GetMapping("/admin/donors") public List<DonorView> adminDonors(@RequestParam(required=false) String bloodGroup,@RequestParam(required=false) String city,@RequestParam(required=false) String state){return bloodGroup==null&&city==null&&state==null?donors.findAll().stream().map(this::dv).toList():donors.search(bloodGroup==null?null:group(bloodGroup),blank(city),blank(state)).stream().map(this::dv).toList();}
 @GetMapping("/admin/donors/{id}") public DonorView donor(@PathVariable Long id){return dv(donors.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Donor not found")));}
 @PatchMapping("/admin/donors/{id}/status") public DonorView donorStatus(@PathVariable Long id,@RequestBody AvailabilityInput in){Donor d=donors.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Donor not found"));d.available=Boolean.TRUE.equals(in.available());return dv(donors.save(d));}
 @GetMapping("/admin/users") public List<UserView> adminUsers(){return users.findAll().stream().map(this::uv).toList();}
 @PatchMapping("/admin/users/{id}/status") public UserView userStatus(@PathVariable Long id,@RequestBody AvailabilityInput in){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));u.enabled=Boolean.TRUE.equals(in.available());return uv(users.save(u));}
 @GetMapping("/admin/donations") public List<Map<String,Object>> allDonations(){return donations.findAll().stream().map(this::donationView).toList();}
 @GetMapping("/donations/my") public List<Map<String,Object>> myDonations(){return donations.findByDonorUserIdOrderByDonationDateDesc(current().id).stream().map(this::donationView).toList();}
 @PostMapping("/admin/donations") @Transactional public ResponseEntity<?> recordDonation(@RequestBody Map<String,Object> in){Long id=Long.valueOf(in.get("donorId").toString());Donation d=new Donation();d.donor=donors.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Donor not found"));d.donationDate=LocalDate.parse(in.get("donationDate").toString());d.unitsDonated=in.get("unitsDonated")==null?null:Integer.valueOf(in.get("unitsDonated").toString());d.hospitalOrCenter=Objects.toString(in.get("hospitalOrCenter"),"Recorded donation");d.notes=Objects.toString(in.get("notes"),"");if(in.get("requestId")!=null)d.bloodRequest=requests.findById(Long.valueOf(in.get("requestId").toString())).orElse(null);return ResponseEntity.status(201).body(donationView(donations.save(d)));}
 private Map<String,Object> donationView(Donation d){return Map.of("id",d.id,"donor",d.donor.user.fullName,"bloodGroup",d.donor.bloodGroup.name(),"donationDate",d.donationDate,"unitsDonated",Objects.toString(d.unitsDonated,""),"hospitalOrCenter",d.hospitalOrCenter,"status",d.status);}
 @GetMapping("/dashboard/stats") public Map<String,Long> stats(){return Map.of("totalDonors",donors.count(),"availableDonors",donors.countByAvailableTrue(),"totalRequests",requests.count());}
 @GetMapping("/admin/dashboard/stats") public Map<String,Long> adminStats(){return Map.of("totalDonors",donors.count(),"availableDonors",donors.countByAvailableTrue(),"totalRequesters",users.countByRole(Role.REQUESTER),"totalRequests",requests.count(),"pendingRequests",requests.countByStatus(RequestStatus.PENDING),"approvedRequests",requests.countByStatus(RequestStatus.APPROVED),"fulfilledRequests",requests.countByStatus(RequestStatus.FULFILLED));}
 @GetMapping("/admin/reports/donors-by-blood-group") public Map<String,Long> donorReport(){Map<String,Long> m=new LinkedHashMap<>();for(Object[] a:donors.countByGroup())m.put(a[0].toString(),(Long)a[1]);return m;}
 @GetMapping("/admin/reports/requests-by-status") public Map<String,Long> requestReport(){Map<String,Long> m=new LinkedHashMap<>();for(Object[] a:requests.countByStatus())m.put(a[0].toString(),(Long)a[1]);return m;}
 private String blank(String s){return s==null||s.isBlank()?null:s.trim();}
}
